// Замеры читаемости текста для тестов «зум 200%» (план .qa/e2e/specs/zoom-200.md). Только чтение DOM.
import type { Locator, Page } from '@playwright/test';

/** Viewport «200%» для телефона 390×844 — как в проверке 08.11 (у разработчика ещё 178 pt — не проверялось нами). */
export const ZOOM200_VIEWPORT = { width: 195, height: 422 };

export type TextLayout = {
  text: string;
  lines: number;          // число строк текста (по разным top у прямоугольников)
  brokenWords: string[];  // слова, которые разорваны между строками
  ellipsized: boolean;    // обрезан «…» (text-overflow / line-clamp) — scrollWidth/scrollHeight больше видимого
  left: number; right: number; top: number; bottom: number;
  viewportWidth: number;
};

/** Разметка текста элемента: строки, разорванные слова, многоточие, рамка. */
export async function textLayout(loc: Locator): Promise<TextLayout> {
  return loc.evaluate((el: Element) => {
    const lineTops = (rects: DOMRectList | DOMRect[]) => {
      const tops: number[] = [];
      for (const r of Array.from(rects)) {
        if (r.width < 1 || r.height < 1) continue;
        if (!tops.some((t) => Math.abs(t - r.top) < r.height / 2)) tops.push(r.top);
      }
      return tops.length;
    };
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    const broken: string[] = [];
    const all = document.createRange();
    all.selectNodeContents(el);
    let n: Node | null;
    while ((n = walker.nextNode())) {
      const s = n.textContent ?? '';
      const re = /\S+/g;
      let m: RegExpExecArray | null;
      while ((m = re.exec(s))) {
        const r = document.createRange();
        r.setStart(n, m.index);
        r.setEnd(n, m.index + m[0].length);
        if (lineTops(r.getClientRects()) > 1) broken.push(m[0]);
      }
    }
    const h = el as HTMLElement;
    const ellipsized = [h, ...Array.from(h.querySelectorAll<HTMLElement>('*'))].some(
      (e) => e.scrollWidth > e.clientWidth + 1 || (getComputedStyle(e).webkitLineClamp !== 'none' && e.scrollHeight > e.clientHeight + 1),
    );
    const b = el.getBoundingClientRect();
    return {
      text: (el.textContent ?? '').trim(),
      lines: lineTops(all.getClientRects()),
      brokenWords: broken,
      ellipsized,
      left: b.left, right: b.right, top: b.top, bottom: b.bottom,
      viewportWidth: document.documentElement.clientWidth,
    };
  });
}

/** Рамка элемента целиком в окне по ширине (допуск 1 px). */
export function insideViewportX(l: Pick<TextLayout, 'left' | 'right' | 'viewportWidth'>) {
  return l.left >= -1 && l.right <= l.viewportWidth + 1;
}

/** Пересекаются ли рамки двух элементов. */
export async function boxesOverlap(a: Locator, b: Locator) {
  const [x, y] = [await a.boundingBox(), await b.boundingBox()];
  if (!x || !y) throw new Error('элемент без рамки');
  return x.x < y.x + y.width && y.x < x.x + x.width && x.y < y.y + y.height && y.y < x.y + x.height;
}

/** Нет горизонтальной прокрутки страницы. */
export async function noHorizontalScroll(page: Page) {
  return page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth + 1);
}

/** Placeholder поля помещается целиком: ширина текста (canvas, шрифт поля) ≤ ширина содержимого поля. */
export async function placeholderFits(input: Locator) {
  return input.evaluate((el: Element) => {
    const i = el as HTMLInputElement;
    const cs = getComputedStyle(i);
    const ctx = document.createElement('canvas').getContext('2d')!;
    ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
    const textW = ctx.measureText(i.placeholder).width;
    const boxW = i.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
    return { placeholder: i.placeholder, textW, boxW, fits: textW <= boxW + 1 };
  });
}
